#!/usr/bin/env python3
"""Record confirmed final writes and return the milestone; no further uploads."""
import pathlib,json,datetime
R=pathlib.Path(__file__).resolve().parents[2]
def read(p):return json.loads((R/p).read_text())
def write(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
results=read('protocols/c006-final-upload.json')['results'];assert len(results)==2 and all(x['status']=='succeeded' for x in results);source,progress=results;assert source['library_file_id']=='libfile_674e2225af5c8191b0e6d5730cc844e5' and progress['library_file_id']=='libfile_85f35e0e1c2c81918858d737069b5c49'
now=datetime.datetime.now(datetime.timezone.utc).isoformat();raw=read('protocols/receipts/c006-qualified-round.json');prepared=read('protocols/checkpoint-c006-final-prepared.json');accepted=read('ACCEPTED.json');decision=read('outer/c006/decision.json')
receipt={'schema':'adaptive-final-round-save/1','round':'c006','savedAt':now,'sourceLibraryFileId':source['library_file_id'],'sourceVersion':source['current_version_number'],'archiveSHA256':prepared['archiveSHA256'],'bytes':prepared['bytes'],'rawLibraryFileId':raw['libraryFileId'],'rawVersion':raw['currentVersion'],'progressLibraryFileId':progress['library_file_id'],'progressVersion':progress['current_version_number'],'remoteBytesVerified':False};write('protocols/receipts/c006-final.json',receipt)
st=read('STATUS.json');st.update(state='c006-durably-closed',phase='closed',formalCompleted=decision['formalSlots'],formalUnstarted=decision['unstartedSlots'],currentAcceptedVersion=accepted['version'],latestAcceptedVersion=accepted['version'],accepted=accepted['version'],updatedAt=now,durableSource={'libraryFileId':source['library_file_id'],'version':source['current_version_number']});write('STATUS.json',st)
t=read('outer/c006/timing.json');t.update(finalSourceSaveConfirmedAt=now,awaiting=None);write('outer/c006/timing.json',t)
lib=read('protocols/LIBRARY.json');lib.update(source=source,progress=progress,c006Raw=read('outer/c006/raw-library-upload.json')['results'][0]);write('protocols/LIBRARY.json',lib)
v=read('outer/c006/visual-site-manifest-v1.json');featured=v.get('featuredAssets');assert isinstance(featured,list) and 4<=len(featured)<=6
milestone={'schema':'adaptive-general-site-milestone/1','batch':'adaptive-general-twelve','round':'c006','status':decision['status'],'durable':True,'completed':6,'planned':12,'acceptedVersion':accepted['version'],'baseline':'adaptive-general-laser-current-successor-v1','decision':'outer/c006/decision.json','report':'outer/c006/REPORT.zh-CN.md','rule':'outer/c006/rule.json','skill':'outer/c006/GENERATING-SKILL.zh-CN.md','gapResults':'outer/c006/gap-results.json','acceptedPointer':'outer/c006/accepted-pointer.json','rawArchive':raw,'finalSourceSave':receipt,'visualManifest':'outer/c006/visual-site-manifest-v1.json','featuredAssets':featured,'fullVisualManifest':v,'cost':decision['cost'],'unknown':['arbitrary dependencies and relocation','new internal visual patterns','whole-image symmetry','continuous-neighborhood robustness','human tolerance and fairness','human fun']};write('outer/c006/site-milestone.json',milestone)
print(json.dumps({'status':decision['status'],'accepted':accepted['version'],'sourceVersion':source['current_version_number'],'progressVersion':progress['current_version_number'],'rawLibraryFileId':raw['libraryFileId'],'rawVersion':raw['currentVersion'],'milestone':'outer/c006/site-milestone.json','featuredAssets':len(featured)}))
